import sys
import numpy as np
sys.path.insert(0, 'source')
import pybamm

def solve(direction, n, bc, source, speed, t_final):
    x = pybamm.SpatialVariable('x', domain='d', coord_sys='cartesian')
    u = pybamm.Variable('u', domain='d')
    if direction == 'upwind':
        edge, side = pybamm.upwind(u), 'left'
    else:
        edge, side = pybamm.downwind(u), 'right'
    velocity = pybamm.PrimaryBroadcastToEdges(speed, ['d'])
    model = pybamm.BaseModel()
    model.rhs = {u: -pybamm.div(edge * velocity) + source}
    model.initial_conditions = {u: pybamm.Scalar(0)}
    model.boundary_conditions = {u: {side: (pybamm.Scalar(bc), 'Dirichlet')}}
    model.variables = {'u': u}
    geometry = {'d': {x: {'min': 0, 'max': 1}}}
    mesh = pybamm.Mesh(geometry, {'d': pybamm.Uniform1DSubMesh}, {x: n})
    disc = pybamm.Discretisation(mesh, {'d': pybamm.FiniteVolume()})
    processed = disc.process_model(model, inplace=False)
    solution = pybamm.ScipySolver(method='BDF').solve(
        processed, np.linspace(0, t_final, 9)
    )
    return np.asarray(solution['u'].entries[:, -1])

cases = [
    ('upwind', 1, 2.5, 0.0, 0.3, 0.2),
    ('upwind', 29, -0.4, 1.2, 2.1, 0.35),
    ('downwind', 2, 1.1, -0.2, -0.25, 0.4),
    ('downwind', 31, -2.0, 0.8, -3.0, 0.25),
]
for case in cases:
    values = solve(*case)
    assert values.size == case[1]
    assert np.all(np.isfinite(values))
    print(case[0], case[1], float(values.min()), float(values.max()))
